/* Styles for REST-R08 replica – WCAG 2.2 AA baseline */
:root {
  --color-bg: #fafafa;
  --color-fg: #222;
  --color-primary: #8b4513;
  --color-primary-dark: #65320f;
  --color-accent: #d2691e;
  --color-muted: #666;
  --color-border: #ccc;
  --color-success: #2e8b57;
  --color-error: #b22222;
  --font-sans: system-ui, sans-serif;
  --radius: 0.4rem;
  --transition: 0.2s ease-in-out;
}

/* Reset */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html { font-size: 100%; scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: var(--color-fg);
  line-height: 1.5;
}
img, svg { max-width: 100%; height: auto; display: block; }
a { color: var(--color-primary); text-decoration: underline; }
a:hover,
a:focus { color: var(--color-primary-dark); }
button,
input,
select,
textarea {
  font: inherit;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-primary);
  color: #fff;
  padding: 8px 16px;
  z-index: 100;
}
.skip-link:focus {
  top: 0;
}

/* Layout containers */
header,
nav,
main,
footer {
  padding: 1rem;
}
.container {
  max-width: 1200px;
  margin: 0 auto;
}

/* Header */
.site-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  background: var(--color-primary);
  color: #fff;
  padding: 0.5rem 1rem;
}
.site-header[data-component="site-header"] {
  gap: 1rem;
}
.site-logo {
  font-size: 1.25rem;
  font-weight: bold;
  color: #fff;
  text-decoration: none;
}
.age-gate-trigger {
  background: transparent;
  border: 2px solid #fff;
  color: #fff;
  padding: 0.25rem 0.5rem;
  border-radius: var(--radius);
  cursor: pointer;
}
.age-gate-trigger:hover,
.age-gate-trigger:focus {
  background: rgba(255,255,255,0.2);
}

/* Nav */
.primary-nav {
  background: var(--color-primary-dark);
}
.nav-container {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
}
.nav-menu {
  list-style: none;
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}
.nav-menu li a {
  display: block;
  padding: 0.5rem 0.75rem;
  color: #fff;
  text-decoration: none;
}
.nav-menu li a:hover,
.nav-menu li a:focus {
  background: var(--color-accent);
  border-radius: var(--radius);
}
.nav-toggle {
  display: none;
  background: transparent;
  border: none;
  color: #fff;
  font-size: 1.5rem;
  cursor: pointer;
}

/* Hero */
.hero {
  background: #fff8f0;
  color: var(--color-fg);
  text-align: center;
  padding: 3rem 1rem;
}
.hero h1 {
  font-size: 2rem;
  margin-bottom: 0.5rem;
}
.hero p {
  font-size: 1.125rem;
  margin-bottom: 1.5rem;
}
.hero .btn {
  background: var(--color-primary);
  color: #fff;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  cursor: pointer;
}
.hero .btn:hover,
.hero .btn:focus {
  background: var(--color-primary-dark);
}

/* Main content */
main {
  min-height: calc(100vh - (header + footer));
}
.content-band {
  background: #fff;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  margin: 1rem 0;
  padding: 1.5rem;
}
.content-band[data-component="content-band"] {
  /* generic wrapper */
}

/* Menu filter */
.menu-filter {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 1rem;
}
.menu-filter label {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  cursor: pointer;
}
.menu-filter input[type="checkbox"] {
  width: 1rem;
  height: 1rem;
}

/* Menu grid */
.menu-grid {
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
}
.menu-card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 1rem;
  background: #fafafa;
}
.menu-card h3 {
  margin: 0 0 0.25rem;
}
.menu-card .price {
  font-weight: bold;
  color: var(--color-primary);
}
.menu-card .tags {
  margin-top: 0.5rem;
  font-size: 0.875rem;
  color: var(--color-muted);
}
.menu-card .tags span {
  display: inline-block;
  background: #eee;
  padding: 0.1rem 0.4rem;
  border-radius: 0.2rem;
  margin-right: 0.25rem;
}

/* Reservation form */
.reservation-form {
  display: grid;
  gap: 0.75rem;
}
.reservation-form label {
  display: flex;
  flex-direction: column;
}
.reservation-form input,
.reservation-form select {
  padding: 0.5rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  width: 100%;
}
.reservation-form button {
  background: var(--color-primary);
  color: #fff;
  border: none;
  padding: 0.75rem;
  border-radius: var(--radius);
  cursor: pointer;
}
.reservation-form button:hover,
.reservation-form button:focus {
  background: var(--color-primary-dark);
}

/* Location cards */
.locations-grid {
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
}
.location-card {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 1rem;
  background: #fafafa;
}
.location-card h3 {
  margin-top: 0;
}
.location-card .hours {
  font-weight: 500;
}
.location-card .status {
  font-size: 0.875rem;
  padding: 0.2rem 0.5rem;
  border-radius: 0.2rem;
  display: inline-block;
  margin-top: 0.25rem;
}
.status.open { background: #e0f8e9; color: #2e8b57; }
.status.closed { background: #f8d7da; color: #b22222; }

/* Press list */
.press-list {
  display: grid;
  gap: 1rem;
}
.press-item {
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 1rem;
  background: #fafafa;
}
.press-item h3 { margin: 0 0 0.25rem; }
.press-item .date { color: var(--color-muted); font-size: 0.875rem; }
.press-item p { margin: 0.5rem 0 0; }

/* Footer */
.site-footer {
  background: var(--color-primary-dark);
  color: #eee;
}
.footer-container {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  justify-content: space-between;
}
.footer-section {
  flex: 1 1 200px;
}
.footer-section h4 {
  margin-top: 0;
  margin-bottom: 0.5rem;
  color: #fff;
}
.footer-section ul {
  list-style: none;
  padding: 0;
}
.footer-section li a {
  color: #ccc;
  text-decoration: none;
}
.footer-section li a:hover,
.footer-section li a:focus {
  color: #fff;
}
.newsletter-form {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.newsletter-form input[type="email"] {
  padding: 0.5rem;
  border: 1px solid #555;
  border-radius: var(--radius);
  flex: 1 1 150px;
}
.newsletter-form button {
  background: var(--color-primary);
  color: #fff;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  cursor: pointer;
}
.newsletter-form button:hover,
.newsletter-form button:focus {
  background: var(--color-primary-dark);
}

/* Age gate modal */
#age-gate-modal {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.6);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 1000;
}
#age-gate-modal[aria-hidden="false"] {
  display: flex;
}
.age-gate-dialog {
  background: #fff;
  color: var(--color-fg);
  padding: 2rem;
  border-radius: var(--radius);
  max-width: 90%;
  width: 320px;
  text-align: center;
  position: relative;
}
.age-gate-dialog h2 {
  margin-top: 0;
}
.age-gate-dialog button {
  margin-top: 1.5rem;
  background: var(--color-primary);
  color: #fff;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius);
  cursor: pointer;
}
.age-gate-dialog button:hover,
.age-gate-dialog button:focus {
  background: var(--color-primary-dark);
}

/* Focus visible */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Responsive */
@media (max-width: 600px) {
  .nav-toggle { display: block; }
  .nav-menu {
